```swift
func apply(_ operation: (Int) -> Int, to value: Int) -> Int {
    return operation(value)
}
func makeCounter(start: Int) -> () -> Int {
    var current = start
    return {
        current += 1
        return current
    }
}
let twice: (Int) -> Int = { value in return value * 2 }
print(apply(twice, to: 6))
let counter = makeCounter(start: 2)
let alias = counter
let other = makeCounter(start: 2)
print(counter())
print(alias())
print(other())
```
The output is `12`, `3`, `4`, `3`. The first call doubles 6. The counter and its alias share a count, while the separately created counter has its own count.
